CREATE TABLE folders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,UNIQUE KEY folders_workspace_name_unique(workspace_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE campaigns(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,status ENUM('active','paused','completed') NOT NULL DEFAULT 'active',conversion_count BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,KEY campaigns_workspace_status_idx(workspace_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tags(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,color CHAR(7) NOT NULL DEFAULT '#64748b',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,UNIQUE KEY tags_workspace_name_unique(workspace_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE short_links(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,code VARCHAR(64) NOT NULL,domain VARCHAR(255) NOT NULL DEFAULT '',destination TEXT NOT NULL,title VARCHAR(255) NOT NULL DEFAULT '',status ENUM('active','paused','expired') NOT NULL DEFAULT 'active',redirect_status SMALLINT UNSIGNED NOT NULL DEFAULT 302,password_hash VARCHAR(255) NULL,expires_at DATETIME NULL,max_clicks BIGINT UNSIGNED NULL,one_time BOOLEAN NOT NULL DEFAULT FALSE,folder_id BIGINT UNSIGNED NULL,campaign_id BIGINT UNSIGNED NULL,utm JSON NULL,routing_rules JSON NULL,ab_destinations JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(folder_id) REFERENCES folders(id) ON DELETE SET NULL,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE SET NULL,UNIQUE KEY links_domain_code_unique(domain,code),KEY links_workspace_status_created_idx(workspace_id,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE link_tags(link_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(link_id,tag_id),FOREIGN KEY(link_id) REFERENCES short_links(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
